items_in = _items
data = items_in[0]["json"]
worktime = data.get("worktime", [])
absence = data.get("absence", [])
payroll = data.get("payroll", [])
anomalies = []

def add_anomaly(rule, severity, employee_id, employee_name, detail, suggestion):
    anomalies.append({
        "rule": rule,
        "severity": severity,
        "employee_id": employee_id,
        "employee_name": employee_name,
        "detail": detail,
        "suggestion": suggestion
    })

def is_valid_date(date_str):
    try:
        parts = str(date_str).split("/")
        if len(parts) != 3:
            return False
        day, month, year = int(parts[0]), int(parts[1]), int(parts[2])
        if month < 1 or month > 12:
            return False
        if day < 1 or day > 31:
            return False
        if year < 2000 or year > 2100:
            return False
        days_in_month = [0,31,28,31,30,31,30,31,31,30,31,30,31]
        if day > days_in_month[month]:
            return False
        return True
    except:
        return False

def safe_float(val):
    try:
        if val in [None, ""]:
            return None
        return float(val)
    except:
        return None

payroll_ids = set()
for p in payroll:
    if p["employee_id"]:
        payroll_ids.add(p["employee_id"])

worktime_ids = set()
for w in worktime:
    if w["employee_id"]:
        worktime_ids.add(w["employee_id"])

absence_ids = set()
for a in absence:
    if a["employee_id"]:
        absence_ids.add(a["employee_id"])

seen_worktime = {}
for row in worktime:
    eid = row["employee_id"]
    name = row["employee_name"]

    if not eid:
        add_anomaly("MISSING_EMPLOYEE_ID", "HIGH", eid, name,
            f"Row has no employee ID — name: {name}",
            "Assign correct employee ID before processing payroll")

    if not name:
        add_anomaly("MISSING_EMPLOYEE_NAME", "HIGH", eid, name,
            f"Employee ID {eid} has no name",
            "Check employee master data for this ID")

    if not row["cost_center"]:
        add_anomaly("MISSING_COST_CENTER", "MEDIUM", eid, name,
            f"{name} has no cost center assigned",
            "Assign cost center before payroll finalization")

    if not is_valid_date(row["date"]):
        add_anomaly("INVALID_DATE", "HIGH", eid, name,
            f"{name} has invalid date: {row['date']}",
            "Correct the date to a valid calendar date")

    hours = safe_float(row["hours_worked"])

    if hours is None:
        add_anomaly("MISSING_HOURS", "HIGH", eid, name,
            f"{name} has missing hours on {row['date']}",
            "Verify timesheet and enter correct hours")

    if hours is not None:
        if hours < 0:
            add_anomaly("NEGATIVE_HOURS", "HIGH", eid, name,
                f"{name} has negative hours ({hours}) on {row['date']}",
                "Correct entry — hours cannot be negative")

        if hours > 16:
            add_anomaly("SUSPICIOUS_HOURS", "HIGH", eid, name,
                f"{name} recorded {hours} hours on {row['date']} — exceeds 16h limit",
                "Verify with manager — likely data entry error")

        if hours > 8:
            add_anomaly("OVERTIME_DETECTED", "MEDIUM", eid, name,
                f"{name} worked {hours} hours on {row['date']} — overtime detected",
                "Verify overtime is approved and matches payroll overtime entry")

    key = f"{eid}_{row['date']}"
    if key in seen_worktime:
        add_anomaly("DUPLICATE_ENTRY", "HIGH", eid, name,
            f"{name} has duplicate worktime entry on {row['date']}",
            "Remove duplicate entry and verify correct hours")
    else:
        seen_worktime[key] = True

    if eid and eid not in payroll_ids:
        add_anomaly("MISSING_PAYROLL_MAPPING", "HIGH", eid, name,
            f"{name} ({eid}) exists in worktime but not in payroll",
            "Add employee to payroll or investigate why they are missing")

for row in absence:
    eid = row["employee_id"]
    name = row["employee_name"]

    if not is_valid_date(row["date"]):
        add_anomaly("INVALID_DATE", "HIGH", eid, name,
            f"{name} has invalid absence date: {row['date']}",
            "Correct the date to a valid calendar date")

    if eid and eid not in worktime_ids:
        add_anomaly("ABSENCE_NO_WORKTIME", "MEDIUM", eid, name,
            f"{name} has absence record but no worktime entries",
            "Verify if employee was active during this period")

    for wrow in worktime:
        if wrow["employee_id"] == eid and wrow["date"] == row["date"]:
            w_hours = safe_float(wrow["hours_worked"])
            if w_hours and w_hours > 0:
                add_anomaly("ABSENCE_WORKTIME_CONFLICT", "HIGH", eid, name,
                    f"{name} has both absence and {w_hours} worktime hours on {row['date']}",
                    "Reconcile — employee cannot be absent and working on the same day")

seen_payroll = {}
for row in payroll:
    eid = row["employee_id"]
    name = row["employee_name"]

    if str(row["status"]).lower() == "inactive":
        add_anomaly("INACTIVE_EMPLOYEE_PAYROLL", "HIGH", eid, name,
            f"{name} ({eid}) is inactive but has a payroll entry",
            "Remove payroll entry or reactivate employee if error")

    if not row["cost_center"]:
        add_anomaly("MISSING_COST_CENTER", "MEDIUM", eid, name,
            f"{name} has no cost center in payroll",
            "Assign cost center before payroll finalization")

    if eid and eid not in worktime_ids:
        add_anomaly("PAYROLL_NO_WORKTIME", "HIGH", eid, name,
            f"{name} ({eid}) is in payroll but has no worktime entries",
            "Verify employee worked this period or remove payroll entry")

    payroll_overtime = safe_float(row["overtime_hours"]) or 0

    worktime_overtime = 0
    for w in worktime:
        if w["employee_id"] == eid:
            h = safe_float(w["hours_worked"])
            if h and h > 8:
                worktime_overtime += h - 8

    if abs(payroll_overtime - worktime_overtime) > 1:
        add_anomaly("OVERTIME_MISMATCH", "HIGH", eid, name,
            f"{name} payroll overtime={payroll_overtime}h but worktime overtime={round(worktime_overtime, 1)}h",
            "Reconcile overtime hours between worktime records and payroll entry")

    key = f"{eid}_{row['pay_period']}"
    if key in seen_payroll:
        add_anomaly("DUPLICATE_PAYROLL", "HIGH", eid, name,
            f"{name} has duplicate payroll entry for {row['pay_period']}",
            "Remove duplicate payroll entry immediately")
    else:
        seen_payroll[key] = True

return [{
    "json": {
        "worktime": worktime,
        "absence": absence,
        "payroll": payroll,
        "anomalies": anomalies
    }
}]

