items_in = _items

data = items_in[0]["json"]

llm_text = data.get("text", "")

summary = data.get("summary", {})
employee_totals = data.get("employee_totals", [])
anomalies = data.get("anomalies", [])

report = f"""
PAYROLL VALIDATION REPORT

Status: {summary.get('status', 'UNKNOWN')}

==================================================
EXECUTIVE SUMMARY
==================================================

{llm_text}

==================================================
SUMMARY METRICS
==================================================

Total Employees: {summary.get('total_employees', 0)}
Total Anomalies: {summary.get('total_anomalies', 0)}
High Severity Issues: {summary.get('high_severity', 0)}
Medium Severity Issues: {summary.get('medium_severity', 0)}

==================================================
EMPLOYEE HOURS SUMMARY
==================================================
"""

for emp in employee_totals:
    report += (
        f"\nEmployee ID: {emp.get('employee_id', '')}\n"
        f"Name: {emp.get('employee_name', '')}\n"
        f"Total Hours: {round(emp.get('total_hours', 0), 1)}\n"
        f"Overtime Hours: {round(emp.get('overtime_hours', 0), 1)}\n"
        f"Days Worked: {emp.get('days_worked', 0)}\n"
        f"\n--------------------------------------------------\n"
    )

report += "\n==================================================\n"
report += "ANOMALIES DETECTED\n"
report += "==================================================\n"

for a in anomalies:
    report += (
        f"\nSeverity: {a.get('severity', '')}\n"
        f"Rule: {a.get('rule', '')}\n"
        f"Employee ID: {a.get('employee_id', '')}\n"
        f"Employee Name: {a.get('employee_name', '')}\n"
        f"\nDetail:\n{a.get('detail', '')}\n"
        f"\nSuggestion:\n{a.get('suggestion', '')}\n"
        f"\n--------------------------------------------------\n"
    )

report += """
==================================================
END OF REPORT
==================================================

Generated automatically by Payroll Validation Agent
"""

requests = [
    {
        "insertText": {
            "location": {
                "index": 1
            },
            "text": report
        }
    }
]

return [{
    "json": {
        "report_text": report,
        "requestBody": {
            "requests": requests
        }
    }
}]
